    logoImage: 'rounded-xl',
    socialButtonsBlockButton: 'border-[#ded8ca] bg-[#fffdf8]',
    formButtonPrimary: 'bg-[#17645f] hover:bg-[#12544f]',
    formFieldInput: 'border-[#ded8ca] bg-[#f8f4eb]',
